(()=>{"use strict";var __webpack_modules__={117:()=>{eval('{\n;// ./src/todo.js\nclass Todo {\n  constructor(title, isCompleted = false) {\n    this.title = title;\n    this.isCompleted = isCompleted;\n  }\n\n  render() {\n    const node = document.createElement("div");\n    node.className = "todo";\n\n    const checkbox = document.createElement("input");\n    checkbox.type = "checkbox";\n    checkbox.checked = this.isCompleted;\n\n    checkbox.addEventListener("change", () => {\n      this.isCompleted = checkbox.checked;\n      node.style.textDecoration = this.isCompleted ? "line-through" : "none";\n    });\n\n    const label = document.createElement("label");\n    label.textContent = this.title;\n\n    node.appendChild(checkbox);\n    node.appendChild(label);\n\n    return node;\n  }\n}\n;// ./src/list.js\nclass List {\n  constructor(title) {\n    this.title = title;\n    this.todos = [];\n  }\n\n  render() {\n    const node = document.createElement("div");\n    node.classList.add("list");\n\n    const title = document.createElement("h3");\n    title.textContent = this.title;\n\n    const todosContainer = document.createElement("div");\n    todosContainer.id = "todos";\n    this.todos.forEach((todo) => {\n      const todoItem = todo.render();\n      todosContainer.appendChild(todoItem);\n    });\n\n    node.appendChild(title);\n    node.appendChild(todosContainer);\n\n    return node;\n  }\n\n  addTodo(todo) {\n    this.todos.push(todo);\n  }\n\n  removeTodo(todo) {\n    this.todos = this.todos.filter((t) => t !== todo);\n  }\n}\n\nconst lists = [\n  new List("Inbox"),\n  new List("Next Actions"),\n  new List("Someday/Maybe"),\n];\n\n;// ./src/index.js\n\n\n\nconst titleField = document.getElementById("title-field");\nconst listField = document.getElementById("list-field");\nconst addButton = document.getElementById("add-button");\n\nconst listsContainer = document.getElementById("lists");\n\nrenderListPicker();\nrenderLists();\n\naddButton.addEventListener("click", () => {\n  const title = titleField.value;\n  if (title) {\n    const todo = new Todo(title);\n    const list = lists.find((l) => l.title === listField.value);\n    list.addTodo(todo);\n    \n    renderLists();\n    titleField.value = "";\n  }\n});\n\nfunction renderListPicker() {\n  lists.forEach((list) => {\n    const listOption = document.createElement("option");\n    listOption.value = list.title;\n    listOption.textContent = list.title;\n    listField.appendChild(listOption);\n  });\n}\n\nfunction renderLists() {\n  const listItems = [];\n  lists.forEach((list) => {\n    const listItem = list.render();\n    listItems.push(listItem);\n  });\n\n  listsContainer.replaceChildren(...listItems);\n}//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///117\n\n}')}},__webpack_exports__={};__webpack_modules__[117]()})();